const x=$input.first().json;
if (!x || !Array.isArray(x.jobs)) {
  throw new Error('Greenhouse API response does not contain a jobs array. Public board may be unavailable.');
}
return [{json:{rawJobs:x.jobs,board:'CarGurus Early Careers',fetchedAt:new Date().toISOString(),source:'Greenhouse public GET; no credentials'}}];

const payload=$input.first().json;
const strip=(s)=>String(s||'').replace(/<[^>]*>/g,' ').replace(/&nbsp;|&#160;/gi,' ').replace(/&amp;/gi,'&').replace(/&quot;/gi,'"').replace(/&#39;/gi,"'").replace(/\s+/g,' ').trim();
// Default demo skills; a caller (the Telegram controller) may pass the chosen student's skills.
let expected=['Python','SQL','Excel','Power BI'];
try { const s=$('Called by Another Workflow').first().json.skills; if (Array.isArray(s) && s.length) expected=s.map(String); } catch (e) { /* manual run */ }
const jobs=(payload.rawJobs||[]).filter(j=>/\b(intern|internship|co-op|placement)\b/i.test(String(j.title||''))).map(j=>{
 const description=strip(j.content).slice(0,15000);
 const text=(String(j.title||'')+' '+description).toLowerCase();
 const mentionedSkills=expected.filter(s=>new RegExp('\\b'+s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&').replace(/ /g,'\\s+')+'\\b','i').test(text));
 return {jobId:String(j.id||''),title:String(j.title||'Unknown'),company:'CarGurus (public board)',location:String(j.location?.name||'Not listed'),url:String(j.absolute_url||''),updatedAt:String(j.updated_at||''),mentionedSkills,mentionCount:mentionedSkills.length,eligibility:'NOT VERIFIED',score:null,requiresHumanReview:true};
});
jobs.sort((a,b)=>b.mentionCount-a.mentionCount||a.title.localeCompare(b.title));
return [{json:{source:payload.source,board:payload.board,fetchedAt:payload.fetchedAt,totalFetched:payload.rawJobs.length,internshipCount:jobs.length,jobs:jobs.slice(0,12),note:'Keyword mentions are NOT verified job requirements. Eligibility, education, location authorization and experience are NOT evaluated. Never interpret mentionCount as a match score.'}}];

const x=$input.first().json;
let message=`REAL PUBLIC INTERNSHIP LISTINGS (for review)
Source: ${x.board} / Greenhouse
Found ${x.internshipCount} internship-related listings; showing up to 5.

`;
for(const [i,j] of x.jobs.slice(0,5).entries()) {
 message+=`${i+1}. ${j.title}
${j.location}
${j.url}
Terms in description: ${j.mentionedSkills.join(', ')||'none from sample profile'}

`;
}
message+='IMPORTANT: These are real listings, but education, eligibility and skill requirements were NOT verified. No suitability score is assigned.';
return [{json:{...x,shownJobs:x.jobs.slice(0,5),message}}];
